var results=new System.Collections.Generic.List<object>();foreach(var path in new[]{"Assets/Prefabs/NewMap/ArcherTower.prefab","Assets/Prefabs/NewMap/MagicTower.prefab","Assets/Prefabs/NewMap/UnitTower.prefab"}){var root=UnityEditor.PrefabUtility.LoadPrefabContents(path);try{var visual=root.transform.Find("Visual").gameObject;if(UnityEditor.PrefabUtility.IsPartOfPrefabInstance(visual))UnityEditor.PrefabUtility.UnpackPrefabInstance(visual,UnityEditor.PrefabUnpackMode.Completely,UnityEditor.InteractionMode.AutomatedAction);foreach(var l in root.GetComponentsInChildren<Light>(true))UnityEngine.Object.DestroyImmediate(l.gameObject);UnityEditor.PrefabUtility.SaveAsPrefabAsset(root,path);}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}results.Add(new{path,lights=UnityEditor.AssetDatabase.LoadAssetAtPath<GameObject>(path).GetComponentsInChildren<Light>(true).Length});}UnityEditor.AssetDatabase.SaveAssets();return results;
